create table if not exists public.dd_service_normalization_register (id uuid primary key default gen_random_uuid(), division_code text not null, source_service_id uuid references public.dd_master_service_universe(id) on delete restrict, source_name text not null, normalized_action text not null check (normalized_action in ('CANONICAL','ALIAS_REDIRECT','PACKAGE_COMPONENT','ADD_ON','PROGRAM_COMPONENT','MOVE_TO_OTHER_SECTION','PENDING_RECONCILIATION','RETIRED')), canonical_service_id uuid references public.dd_master_service_universe(id) on delete restrict, canonical_name text, reason text not null, evidence_reference text, status text not null default 'LOCKED', created_at timestamptz not null default now(), updated_at timestamptz not null default now()); create index if not exists idx_dd_service_norm_division on public.dd_service_normalization_register(division_code); create index if not exists idx_dd_service_norm_canonical on public.dd_service_normalization_register(canonical_service_id);